// The shared linea_* tool catalog: one definition per tool — name, schema,
// and a handler written against DocumentSession — consumed verbatim by the
// Node MCP server (@lineadraw/mcp, zod shapes) and the in-browser WebMCP layer
// (@lineadraw/editor, JSON Schema via toolJsonSchema). Angles cross this
// boundary in DEGREES (agent ergonomics); tool-arg points are [x, y] tuples
// (see `point` below); points INSIDE object bodies also accept {x, y}.

import { z } from "zod";
import type {
  PointInput,
  QueryFilter,
  RenderPngOptions,
  ToolContext,
} from "./session";

const DEG2RAD = Math.PI / 180;

const box = z
  .object({
    minX: z.number(),
    minY: z.number(),
    maxX: z.number(),
    maxY: z.number(),
  })
  .describe("An axis-aligned box in world mm");

// Deliberately tuple-only, NOT union([tuple, {x,y}]): a bare-anyOf property
// has no top-level `type`, and schema-rebuilding bridges (the WebMCP local
// relay among them) degrade such properties to untyped {} — hosts then
// string-encode the value and every call fails validation. A tuple keeps
// `type: "array"` at the top level everywhere. ({x, y} still parses fine in
// OBJECT bodies — model schemas accept both; this is only the tool-arg form.)
export const point = z
  .tuple([z.number(), z.number()])
  .describe("A world point in mm: [x, y]");

export const looseObject = z
  .record(z.string(), z.unknown())
  .describe(
    'A Linea model object, e.g. {"type":"line","a":[0,0],"b":[100,0]}. ' +
      "Types: line, point (p; paints as a dot sized by lineWidth), " +
      "polyline (points with bulge, closed), circle, arc, " +
      "ellipse, hatch, text, dimension, block. Optional layer (name), " +
      "color (#rrggbb), lineType.",
  );

export const documentId = z
  .string()
  .optional()
  .describe("Document id; omit for the active document");

export interface LineaToolDef {
  name: string;
  title: string;
  description: string;
  /** Zod raw shape — the MCP SDK consumes it verbatim; browser adapters
   * convert via toolJsonSchema and validate via toolArgs. */
  inputSchema: z.ZodRawShape;
  run(
    ctx: ToolContext,
    args: Record<string, unknown>,
  ): unknown | Promise<unknown>;
}

/** Success payload in MCP content shape (text + structuredContent). */
export const toolResult = (data: unknown) => ({
  content: [{ type: "text" as const, text: JSON.stringify(data) }],
  structuredContent: data as Record<string, unknown>,
});

/** A handler result that already IS a CallToolResult (e.g. image content) —
 * runTool passes it through instead of JSON-wrapping it. */
export type RawToolResult = {
  content: ({ type: string } & Record<string, unknown>)[];
  isError?: boolean;
  structuredContent?: Record<string, unknown>;
};

const isRawToolResult = (v: unknown): v is RawToolResult =>
  typeof v === "object" &&
  v !== null &&
  Array.isArray((v as { content?: unknown }).content);

/** Env-neutral bytes → base64 (Node Buffer or the btoa global). */
export const bytesToBase64 = (bytes: Uint8Array): string => {
  if (typeof Buffer !== "undefined") return Buffer.from(bytes).toString("base64");
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
};

/** Error payload in MCP content shape. */
export const toolError = (e: unknown) => ({
  content: [
    { type: "text" as const, text: String(e instanceof Error ? e.message : e) },
  ],
  isError: true as const,
});

/** Parse args against the tool's schema, run it, wrap result/error. */
export const runTool = async (
  def: LineaToolDef,
  ctx: ToolContext,
  args: unknown,
): Promise<
  ReturnType<typeof toolResult> | ReturnType<typeof toolError> | RawToolResult
> => {
  try {
    const parsed = z.object(def.inputSchema).parse(args ?? {});
    const out = await def.run(ctx, parsed);
    return isRawToolResult(out) ? out : toolResult(out);
  } catch (e) {
    return toolError(e);
  }
};

/** The tool's input schema as plain JSON Schema (WebMCP registration). */
export const toolJsonSchema = (def: LineaToolDef): Record<string, unknown> =>
  z.toJSONSchema(z.object(def.inputSchema), { io: "input" }) as Record<
    string,
    unknown
  >;

/** `{documentId, revision, document}` — the payload viewers render. */
const docPayload = (s: {
  id: string;
  revision(): number;
  getDocument(): unknown;
}) => ({
  documentId: s.id,
  revision: s.revision(),
  document: s.getDocument(),
});

type TransformArgs = {
  kind: "move" | "rotate" | "scale" | "mirror" | "copy" | "array";
  ids: string[];
  delta?: PointInput;
  angleDeg?: number;
  factor?: number;
  center?: PointInput;
  axisA?: PointInput;
  axisB?: PointInput;
  count?: number;
  documentId?: string;
};

/**
 * The environment-neutral tools — everything that only needs a document
 * session. Node-only tools (new/open/save/export, the MCP App) live in
 * @lineadraw/mcp; browser-only tools (selection, view, spaces) in @lineadraw/editor.
 */
export const coreLineaTools: LineaToolDef[] = [
  {
    name: "linea_add_objects",
    title: "Add objects",
    description:
      "Add objects to model space (or a paper layout via `layout`). " +
      "Returns the created ids.",
    inputSchema: {
      objects: z.array(looseObject).min(1),
      layout: z
        .string()
        .optional()
        .describe("Layout name/id for sheet annotations"),
      documentId,
    },
    run(ctx, args) {
      const { objects, layout, documentId: idArg } = args as {
        objects: Record<string, unknown>[];
        layout?: string;
        documentId?: string;
      };
      const s = ctx.get(idArg);
      const ids = s.add(objects, { layout });
      return { ids, revision: s.bump() };
    },
  },
  {
    name: "linea_update_objects",
    title: "Update objects",
    description:
      "Patch objects by id: entries are {id, ...fieldsToChange}. One undo step.",
    inputSchema: {
      entries: z.array(z.record(z.string(), z.unknown())).min(1),
      documentId,
    },
    run(ctx, args) {
      const { entries, documentId: idArg } = args as {
        entries: Record<string, unknown>[];
        documentId?: string;
      };
      const s = ctx.get(idArg);
      s.update(entries as ({ id: string } & Record<string, unknown>)[]);
      return { updated: entries.length, revision: s.bump() };
    },
  },
  {
    name: "linea_remove_objects",
    title: "Remove objects",
    description:
      "Delete objects by id. Unknown ids are skipped; `removed` reports how " +
      "many objects were actually deleted.",
    inputSchema: { ids: z.array(z.string()).min(1), documentId },
    run(ctx, args) {
      const { ids, documentId: idArg } = args as {
        ids: string[];
        documentId?: string;
      };
      const s = ctx.get(idArg);
      const removed = s.remove(ids);
      return { removed, revision: s.bump() };
    },
  },
  {
    name: "linea_transform",
    title: "Transform objects",
    description:
      "move (delta) | rotate (angleDeg, center?) | scale (factor, center?) | " +
      "mirror (axisA, axisB) | copy (delta → new ids) | array (count TOTAL, delta → new ids). " +
      "rotate/scale default their center to the selection bbox center.",
    inputSchema: {
      kind: z.enum(["move", "rotate", "scale", "mirror", "copy", "array"]),
      ids: z.array(z.string()).min(1),
      delta: point.optional(),
      angleDeg: z.number().optional(),
      factor: z.number().optional(),
      center: point.optional(),
      axisA: point.optional(),
      axisB: point.optional(),
      count: z.number().int().optional(),
      documentId,
    },
    run(ctx, args) {
      const a = args as TransformArgs;
      const s = ctx.get(a.documentId);
      const need = <T>(v: T | undefined, name: string): T => {
        if (v === undefined) throw new Error(`${a.kind} requires "${name}"`);
        return v;
      };
      let created: string[] | undefined;
      switch (a.kind) {
        case "move":
          s.move(a.ids, need(a.delta, "delta"));
          break;
        case "rotate":
          s.rotate(a.ids, need(a.angleDeg, "angleDeg") * DEG2RAD, a.center);
          break;
        case "scale":
          s.scale(a.ids, need(a.factor, "factor"), a.center);
          break;
        case "mirror":
          s.mirror(a.ids, need(a.axisA, "axisA"), need(a.axisB, "axisB"));
          break;
        case "copy":
          created = s.copy(a.ids, need(a.delta, "delta"));
          break;
        case "array":
          created = s.array(a.ids, need(a.count, "count"), need(a.delta, "delta"));
          break;
      }
      return { ...(created ? { ids: created } : {}), revision: s.bump() };
    },
  },
  {
    name: "linea_create_layout",
    title: "Create paper layout",
    description:
      "Add a paper layout (default: A3 landscape, one viewport fitted to " +
      'the model extents). scale accepts "1:50" strings.',
    inputSchema: {
      name: z.string(),
      // Named size + optional custom mm — two typed params instead of a
      // union so every property keeps a top-level JSON-schema `type`
      // (see `point` for why bare anyOf properties are relay-hostile).
      sheet: z.enum(["A4", "A3", "A2", "A1", "A0"]).optional(),
      sheetSize: z
        .object({ width: z.number(), height: z.number() })
        .optional()
        .describe("Custom sheet size in mm (overrides `sheet`)"),
      orientation: z.enum(["portrait", "landscape"]).optional(),
      scale: z.string().optional().describe('Viewport scale, e.g. "1:50"'),
      documentId,
    },
    run(ctx, args) {
      const { name, sheet, sheetSize, orientation, scale, documentId: idArg } =
        args as {
          name: string;
          sheet?: "A4" | "A3" | "A2" | "A1" | "A0";
          sheetSize?: { width: number; height: number };
          orientation?: "portrait" | "landscape";
          scale?: string;
          documentId?: string;
        };
      const s = ctx.get(idArg);
      const layoutId = s.createLayout(name, {
        sheet: sheetSize ?? sheet,
        orientation,
        scale,
      });
      return { layoutId, revision: s.bump() };
    },
  },
  {
    name: "linea_update_layout",
    title: "Update layout",
    description:
      "Patch a paper layout's name, sheet size (mm), or print palette " +
      '(printPalette "monochrome" prints/renders everything black).',
    inputSchema: {
      layout: z.string().describe("Layout name/id"),
      name: z.string().optional().describe("New layout name"),
      sheetSize: z
        .object({ width: z.number(), height: z.number() })
        .optional()
        .describe("New sheet size in mm"),
      printPalette: z.enum(["color", "grayscale", "monochrome"]).optional(),
      documentId,
    },
    run(ctx, args) {
      const { layout, name, sheetSize, printPalette, documentId: idArg } =
        args as {
          layout: string;
          name?: string;
          sheetSize?: { width: number; height: number };
          printPalette?: "color" | "grayscale" | "monochrome";
          documentId?: string;
        };
      const s = ctx.get(idArg);
      s.updateLayout(layout, { name, sheet: sheetSize, printPalette });
      return { revision: s.bump() };
    },
  },
  {
    name: "linea_remove_layout",
    title: "Remove layout",
    description: "Delete a paper layout (and its sheet objects) by name or id.",
    inputSchema: {
      layout: z.string().describe("Layout name/id"),
      documentId,
    },
    run(ctx, args) {
      const { layout, documentId: idArg } = args as {
        layout: string;
        documentId?: string;
      };
      const s = ctx.get(idArg);
      s.removeLayout(layout);
      return { revision: s.bump() };
    },
  },
  {
    name: "linea_set_dim_style",
    title: "Set dimension style",
    description:
      "Patch a document dimension style (default: the first): textHeight, " +
      "textOffset, arrowType (filled|open|tick|dot|none), arrowSize, " +
      "extensionType (long|short), extensionOffset, extensionOvershoot, " +
      "precision, font, widthFactor. NOTE: annotation scale is NOT a style " +
      "key — set the top-level `scale` field on each dimension object.",
    inputSchema: {
      patch: z.record(z.string(), z.unknown()),
      styleId: z.string().optional(),
      documentId,
    },
    run(ctx, args) {
      const { patch, styleId, documentId: idArg } = args as {
        patch: Record<string, unknown>;
        styleId?: string;
        documentId?: string;
      };
      const s = ctx.get(idArg);
      s.setDimStyle(patch, styleId);
      return { revision: s.bump() };
    },
  },
  {
    name: "linea_set_text_style",
    title: "Set text style",
    description:
      "Patch a document text style (default: the first): font, widthFactor, " +
      "textHeight (default height for new text), arrowType, arrowSize " +
      "(leader arrows). Per-object styleOverride still wins over the style.",
    inputSchema: {
      patch: z.record(z.string(), z.unknown()),
      styleId: z.string().optional(),
      documentId,
    },
    run(ctx, args) {
      const { patch, styleId, documentId: idArg } = args as {
        patch: Record<string, unknown>;
        styleId?: string;
        documentId?: string;
      };
      const s = ctx.get(idArg);
      s.setTextStyle(patch, styleId);
      return { revision: s.bump() };
    },
  },
  {
    name: "linea_query",
    title: "Query objects",
    description:
      "Filtered read over model-space objects — or one paper layout's sheet " +
      "objects (viewports, annotations) via `layout` — all filters AND: " +
      "type, layer (name), color, lineType, content (text substring), bbox " +
      "(intersects), inside (contained), near ({point, tol}), ids. " +
      "`measure: true` adds bbox/length/area per object. Prefer this over " +
      "linea_get_document — it returns compact data.",
    inputSchema: {
      ids: z.array(z.string()).optional(),
      type: z.string().optional(),
      layer: z.string().optional(),
      color: z.string().optional(),
      lineType: z.string().optional(),
      content: z.string().optional(),
      bbox: box.optional(),
      inside: box.optional(),
      near: z.object({ point, tol: z.number().positive() }).optional(),
      layout: z
        .string()
        .optional()
        .describe("Search this layout's sheet objects (name/id) instead of model space"),
      measure: z.boolean().optional(),
      limit: z
        .number()
        .int()
        .positive()
        .optional()
        .describe("Max objects returned (default 100)"),
      documentId,
    },
    run(ctx, args) {
      const { measure, limit, documentId: idArg, ...filter } = args as {
        measure?: boolean;
        limit?: number;
        documentId?: string;
      } & QueryFilter;
      const s = ctx.get(idArg);
      const all = s.query(filter);
      const cap = limit ?? 100;
      const objects = all.slice(0, cap).map((o) =>
        measure ? { ...o, measure: s.measure(String(o.id)) } : o,
      );
      return { total: all.length, returned: objects.length, objects };
    },
  },
  {
    name: "linea_list_layers",
    title: "List layers",
    description:
      "All layers with full metadata (color, hidden, locked, …) and which " +
      "one is current (the default for new objects).",
    inputSchema: { documentId },
    run(ctx, args) {
      const s = ctx.get((args as { documentId?: string }).documentId);
      return { layers: s.listLayers() };
    },
  },
  {
    name: "linea_layer",
    title: "Manage layers",
    description:
      "add (name, props?) | update (layer, props — rename via props.name) | " +
      "remove (layer; must be empty and not current) | set-current (layer). " +
      "`layer` targets by name or id. Returns the resulting layer list.",
    inputSchema: {
      kind: z.enum(["add", "update", "remove", "set-current"]),
      name: z.string().optional().describe("New layer name (kind: add)"),
      layer: z.string().optional().describe("Target layer name/id"),
      props: z
        .record(z.string(), z.unknown())
        .optional()
        .describe("Layer fields, e.g. {color, hidden, locked, name}"),
      documentId,
    },
    run(ctx, args) {
      const { kind, name, layer, props, documentId: idArg } = args as {
        kind: "add" | "update" | "remove" | "set-current";
        name?: string;
        layer?: string;
        props?: Record<string, unknown>;
        documentId?: string;
      };
      const s = ctx.get(idArg);
      const need = <T>(v: T | undefined, what: string): T => {
        if (v === undefined) throw new Error(`${kind} requires "${what}"`);
        return v;
      };
      let layerId: string | undefined;
      if (kind === "add") layerId = s.addLayer({ ...props, name: need(name, "name") });
      else if (kind === "update") s.updateLayer(need(layer, "layer"), props ?? {});
      else if (kind === "remove") s.removeLayer(need(layer, "layer"));
      else s.setCurrentLayer(need(layer, "layer"));
      return {
        ...(layerId ? { layerId } : {}),
        layers: s.listLayers(),
        revision: s.bump(),
      };
    },
  },
  {
    name: "linea_render",
    title: "Render snapshot",
    description:
      "Render model space (or a paper layout via `layout`) for visual " +
      "verification. svg returns SVG markup as text; png returns an image " +
      "(Node MCP server only — the in-browser editor supports svg).",
    inputSchema: {
      format: z.enum(["svg", "png"]).optional().describe("Default svg"),
      layout: z.string().optional().describe("Layout name/id"),
      bbox: box.optional(),
      padding: z.number().optional().describe("Around the content bbox, mm"),
      width: z.number().int().positive().optional().describe("png only, px"),
      background: z.string().optional().describe("png only, e.g. #ffffff"),
      palette: z
        .enum(["color", "grayscale", "monochrome"])
        .optional()
        .describe(
          "Print-style color remap — use monochrome with a white background " +
            "(light layer colors are authored for the dark canvas)",
        ),
      documentId,
    },
    async run(ctx, args) {
      const { format, documentId: idArg, ...opts } = args as {
        format?: "svg" | "png";
        documentId?: string;
      } & RenderPngOptions;
      const s = ctx.get(idArg);
      if (format === "png") {
        if (!s.renderPng)
          throw new Error(
            "png rendering is only available on the Node MCP server — use format: \"svg\"",
          );
        const bytes = await s.renderPng(opts);
        return {
          content: [
            {
              type: "image" as const,
              data: bytesToBase64(bytes),
              mimeType: "image/png",
            },
          ],
        };
      }
      return { content: [{ type: "text" as const, text: s.renderSvg(opts) }] };
    },
  },
  {
    name: "linea_undo",
    title: "Undo",
    description: "Revert the last change (agent or user edit alike).",
    inputSchema: { documentId },
    run(ctx, args) {
      const s = ctx.get((args as { documentId?: string }).documentId);
      const undone = s.undo();
      return { undone, revision: undone ? s.bump() : s.revision() };
    },
  },
  {
    name: "linea_redo",
    title: "Redo",
    description: "Re-apply the last undone change.",
    inputSchema: { documentId },
    run(ctx, args) {
      const s = ctx.get((args as { documentId?: string }).documentId);
      const redone = s.redo();
      return { redone, revision: redone ? s.bump() : s.revision() };
    },
  },
  {
    name: "linea_summary",
    title: "Document summary",
    description:
      "Counts by type/layer, bbox, layers, layouts — the cheap 'what is in " +
      "this document' observation.",
    inputSchema: { documentId },
    run(ctx, args) {
      const s = ctx.get((args as { documentId?: string }).documentId);
      return { documentId: s.id, revision: s.revision(), ...s.summary() };
    },
  },
  {
    name: "linea_get_document",
    title: "Get document JSON",
    description:
      "The full document (validated .linea JSON) + revision. The in-chat " +
      "viewer calls this to refresh; agents usually want linea_summary instead.",
    inputSchema: { documentId },
    run(ctx, args) {
      return docPayload(ctx.get((args as { documentId?: string }).documentId));
    },
  },
  {
    name: "linea_replace_document",
    title: "Replace document state",
    description:
      "Replace the FULL document with the given .linea JSON (validated + " +
      "migrated). Used by the in-chat editor to persist interactive edits; " +
      "agents should prefer the granular add/update/transform tools.",
    inputSchema: {
      document: z.record(z.string(), z.unknown()),
      documentId,
    },
    run(ctx, args) {
      const { document, documentId: idArg } = args as {
        document: Record<string, unknown>;
        documentId?: string;
      };
      const s = ctx.get(idArg);
      return { documentId: s.id, revision: s.replace(document) };
    },
  },
];
