// In-process document registry: one MCP server session holds live Drawing
// instances keyed by the document's own id (uuid stored IN the file, so
// re-opening the same file targets the same entry). Most tools default to
// the ACTIVE document — the last one created/opened — so single-document
// conversations never pass ids around.

import { Drawing, newDrawing, openDrawing, drawingFromJson } from "@lineadraw/sdk";

export class DocumentRegistry {
  private docs = new Map<string, Drawing>();
  private revisions = new Map<string, number>();
  private activeId: string | null = null;

  create(name?: string): { id: string; doc: Drawing } {
    // Name must go through newDrawing: `doc.document` is a detached-clone
    // getter, so assigning `.name` on it mutates a throwaway copy.
    const doc = newDrawing(name);
    const id = doc.document.id;
    this.docs.set(id, doc);
    this.revisions.set(id, 0);
    this.activeId = id;
    return { id, doc };
  }

  async open(path: string): Promise<{ id: string; doc: Drawing }> {
    const doc = await openDrawing(path);
    const id = doc.document.id;
    this.docs.set(id, doc);
    this.revisions.set(id, 0);
    this.activeId = id;
    return { id, doc };
  }

  /** Resolve a document by id, or the active one when omitted. */
  get(id?: string): { id: string; doc: Drawing } {
    const key = id ?? this.activeId;
    if (!key) throw new Error("No document — call linea_new_document first");
    const doc = this.docs.get(key);
    if (!doc) throw new Error(`Unknown document "${key}"`);
    return { id: key, doc };
  }

  /**
   * Replace a document's full state (validated + migrated) — how in-chat
   * editor edits land. The id must match; conversation undo history resets.
   */
  replace(id: string, raw: unknown): { doc: Drawing; revision: number } {
    if (!this.docs.has(id)) throw new Error(`Unknown document "${id}"`);
    const doc = drawingFromJson(JSON.stringify(raw));
    if (doc.document.id !== id)
      throw new Error(
        `Document id mismatch: payload has "${doc.document.id}", expected "${id}"`,
      );
    this.docs.set(id, doc);
    return { doc, revision: this.bump(id) };
  }

  /** Mark a document changed; the viewer compares revisions to refresh. */
  bump(id: string): number {
    const next = (this.revisions.get(id) ?? 0) + 1;
    this.revisions.set(id, next);
    return next;
  }

  revision(id: string): number {
    return this.revisions.get(id) ?? 0;
  }
}
