// @lineadraw/mcp — MCP server exposing Linea document tools + the in-chat viewer
// (MCP Apps extension). Two transports:
//
// stdio — for hosts that spawn the server as a subprocess (Claude Desktop):
//
//   { "command": "node", "args": ["<abs path>/dist/server.js", "--stdio"] }
//
// Streamable HTTP (default) — Claude's web connectors require an https URL;
// either tunnel plain HTTP (`npx cloudflared tunnel --url http://localhost:3001`)
// or serve TLS locally with a mkcert certificate:
//
//   mkcert -install && mkcert localhost
//   TLS_CERT=./localhost.pem TLS_KEY=./localhost-key.pem npm run serve
//
// and add https://localhost:3001/mcp as the custom connector.

import { readFileSync } from "node:fs";
import https from "node:https";
import cors from "cors";
import express from "express";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { DocumentRegistry } from "./documents.js";
import { registerLineaTools } from "./tools.js";

const PORT = Number(process.env.PORT ?? 3001);

// ONE registry for the process: every MCP session shares the open documents,
// so a reconnecting client keeps its work.
const registry = new DocumentRegistry();

const buildServer = (): McpServer => {
  const server = new McpServer({ name: "Lineadraw CAD", version: "0.1.0" });
  registerLineaTools(server, registry);
  return server;
};

function startHttpServer() {
  const app = express();
  app.use(cors());
  app.use(express.json({ limit: "16mb" }));

  // Log every request — when a connector fails to attach, an EMPTY log tells
  // you the client never reached this server at all (e.g. the check runs from
  // Anthropic infrastructure, which cannot see localhost — use a tunnel).
  app.use((req, _res, next) => {
    console.log(`${new Date().toISOString()} ${req.method} ${req.path}`);
    next();
  });

  // Route ALL methods through the transport: clients probe with GET (SSE
  // stream) and DELETE (session teardown) too, and the transport answers
  // those correctly for a stateless server — an Express 404 would read as
  // "not an MCP server". Served at "/" as well as "/mcp": Claude probes the
  // URL exactly as entered, and a bare origin should still work.
  app.all(["/", "/mcp"], async (req, res) => {
    const transport = new StreamableHTTPServerTransport({
      sessionIdGenerator: undefined,
      enableJsonResponse: true,
    });
    res.on("close", () => transport.close());
    await buildServer().connect(transport);
    await transport.handleRequest(req, res, req.body);
  });

  const { TLS_CERT, TLS_KEY } = process.env;
  if (TLS_CERT && TLS_KEY) {
    https
      .createServer(
        { cert: readFileSync(TLS_CERT), key: readFileSync(TLS_KEY) },
        app,
      )
      .listen(PORT, () => {
        console.log(`Linea MCP server on https://localhost:${PORT}/mcp`);
      });
  } else {
    app.listen(PORT, () => {
      console.log(
        `Linea MCP server on http://localhost:${PORT}/mcp (set TLS_CERT/TLS_KEY for https)`,
      );
    });
  }
}

// stdio mode: stdout carries the JSON-RPC stream, so nothing else may be
// written to it — log to stderr only.
if (process.argv.includes("--stdio")) {
  await buildServer().connect(new StdioServerTransport());
  console.error("Linea MCP server on stdio");
} else {
  startHttpServer();
}
