// Tool layer: the shared linea_* catalog (@lineadraw/mcp-tools) adapted onto
// @lineadraw/sdk's Drawing, plus the Node-only tools (disk I/O, the MCP App).
// Angles cross the tool boundary in DEGREES (handled by the shared handlers);
// object payloads are validated by the SDK's zod schemas.

import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import {
  registerAppTool,
  registerAppResource,
  RESOURCE_MIME_TYPE,
} from "@modelcontextprotocol/ext-apps/server";
import type { Drawing } from "@lineadraw/sdk";
import {
  coreLineaTools,
  documentId,
  runTool,
  toolError,
  toolResult,
  type DocumentSession,
  type ToolContext,
} from "@lineadraw/mcp-tools";
import type { DocumentRegistry } from "./documents.js";

export const EDITOR_RESOURCE_URI = "ui://linea/editor.html";

/** Document JSON + revision — the payload the viewer renders. */
const docPayload = (registry: DocumentRegistry, id: string, doc: Drawing) => ({
  documentId: id,
  revision: registry.revision(id),
  document: doc.document,
});

/** The shared catalog's session, backed by an SDK Drawing in the registry. */
class DrawingSession implements DocumentSession {
  constructor(
    private registry: DocumentRegistry,
    readonly id: string,
    private doc: Drawing,
  ) {}

  revision(): number {
    return this.registry.revision(this.id);
  }
  bump(): number {
    return this.registry.bump(this.id);
  }
  add(objects: Record<string, unknown>[], opts?: { layout?: string }): string[] {
    return this.doc.add(objects as Parameters<Drawing["add"]>[0], {
      layout: opts?.layout,
    });
  }
  update(entries: ({ id: string } & Record<string, unknown>)[]): void {
    this.doc.update(entries);
  }
  remove(ids: string[]): number {
    const removed = ids.filter((id) => this.doc.getObject(id) !== undefined);
    this.doc.remove(ids);
    return removed.length;
  }
  query(filter: Parameters<DocumentSession["query"]>[0]): Record<string, unknown>[] {
    const { ids, ...rest } = filter;
    let objects = this.doc.query(rest as Parameters<Drawing["query"]>[0]);
    if (ids) {
      const wanted = new Set(ids);
      objects = objects.filter((o) => wanted.has(o.id));
    }
    return objects as unknown as Record<string, unknown>[];
  }
  measure(id: string) {
    return {
      bbox: this.doc.bboxOf([id]),
      length: this.doc.length(id),
      area: this.doc.area(id),
    };
  }
  listLayers() {
    const current = this.doc.document.currentLayerId;
    return this.doc.layers.map((l) => ({ ...l, current: l.id === current }));
  }
  addLayer(props: { name: string } & Record<string, unknown>): string {
    return this.doc.addLayer(props as Parameters<Drawing["addLayer"]>[0]);
  }
  updateLayer(nameOrId: string, patch: Record<string, unknown>): void {
    this.doc.updateLayer(nameOrId, patch);
  }
  removeLayer(nameOrId: string): void {
    this.doc.removeLayer(nameOrId);
  }
  setCurrentLayer(nameOrId: string): void {
    this.doc.setCurrentLayer(nameOrId);
  }
  renderSvg(opts: Parameters<DocumentSession["renderSvg"]>[0]): string {
    return this.doc.toSvg(opts);
  }
  renderPng(
    opts: Parameters<NonNullable<DocumentSession["renderPng"]>>[0],
  ): Promise<Uint8Array> {
    return this.doc.toPng(opts);
  }
  undo(): boolean {
    return this.doc.undo();
  }
  redo(): boolean {
    return this.doc.redo();
  }
  move(ids: string[], delta: Parameters<Drawing["move"]>[1]): void {
    this.doc.move(ids, delta);
  }
  rotate(
    ids: string[],
    angleRad: number,
    center?: Parameters<Drawing["rotate"]>[2],
  ): void {
    this.doc.rotate(ids, angleRad, center);
  }
  scale(
    ids: string[],
    factor: number,
    center?: Parameters<Drawing["scale"]>[2],
  ): void {
    this.doc.scale(ids, factor, center);
  }
  mirror(
    ids: string[],
    axisA: Parameters<Drawing["mirror"]>[1],
    axisB: Parameters<Drawing["mirror"]>[2],
  ): void {
    this.doc.mirror(ids, axisA, axisB);
  }
  copy(ids: string[], delta: Parameters<Drawing["copy"]>[1]): string[] {
    return this.doc.copy(ids, delta);
  }
  array(
    ids: string[],
    count: number,
    delta: Parameters<Drawing["array"]>[2],
  ): string[] {
    return this.doc.array(ids, count, delta);
  }
  createLayout(
    name: string,
    opts: {
      sheet?: "A4" | "A3" | "A2" | "A1" | "A0" | { width: number; height: number };
      orientation?: "portrait" | "landscape";
      scale?: string;
    },
  ): string {
    return this.doc.createLayout(name, {
      sheet: opts.sheet,
      orientation: opts.orientation,
      viewport: opts.scale !== undefined ? { scale: opts.scale } : undefined,
    });
  }
  updateLayout(
    nameOrId: string,
    patch: Parameters<DocumentSession["updateLayout"]>[1],
  ): void {
    this.doc.updateLayoutMeta(nameOrId, patch);
  }
  removeLayout(nameOrId: string): void {
    this.doc.removeLayout(nameOrId);
  }
  setDimStyle(patch: Record<string, unknown>, styleId?: string): void {
    this.doc.setDimStyle(patch as Parameters<Drawing["setDimStyle"]>[0], styleId);
  }
  setTextStyle(patch: Record<string, unknown>, styleId?: string): void {
    this.doc.setTextStyle(patch as Parameters<Drawing["setTextStyle"]>[0], styleId);
  }
  summary(): Record<string, unknown> {
    return this.doc.summary() as unknown as Record<string, unknown>;
  }
  getDocument(): unknown {
    return this.doc.document;
  }
  replace(raw: Record<string, unknown>): number {
    return this.registry.replace(this.id, raw).revision;
  }
}

export function registerLineaTools(
  server: McpServer,
  registry: DocumentRegistry,
  opts: { editorHtml?: () => Promise<string> } = {},
): void {
  const ctx: ToolContext = {
    get(idArg?: string) {
      const { id, doc } = registry.get(idArg);
      return new DrawingSession(registry, id, doc);
    },
  };

  // The shared catalog (add/update/remove/transform/query/layers/render/
  // undo/summary/get/replace). runTool's results are valid CallToolResults
  // at runtime; the cast bridges its looser RawToolResult content typing
  // (needed for image content) to the SDK's exact union.
  for (const def of coreLineaTools) {
    server.registerTool(
      def.name,
      {
        title: def.title,
        description: def.description,
        inputSchema: def.inputSchema,
      },
      async (args: unknown) =>
        (await runTool(def, ctx, args)) as CallToolResult,
    );
  }

  // --- Node-only tools: registry lifecycle + disk I/O -----------------------

  const run = <A>(fn: (args: A) => unknown) => {
    return async (args: A) => {
      try {
        return toolResult(await fn(args));
      } catch (e) {
        return toolError(e);
      }
    };
  };

  server.registerTool(
    "linea_new_document",
    {
      title: "New Linea document",
      description:
        "Create a fresh CAD document (mm, Y-up) and make it active. " +
        "Call linea_show_document afterwards to display it in chat.",
      inputSchema: { name: z.string().optional() },
    },
    run(({ name }: { name?: string }) => {
      const { id, doc } = registry.create(name);
      return { documentId: id, summary: doc.summary() };
    }),
  );

  server.registerTool(
    "linea_open_document",
    {
      title: "Open .linea file",
      description:
        "Open a .linea file (or legacy .lineadraw) from disk and make it active.",
      inputSchema: { path: z.string() },
    },
    run(async ({ path: p }: { path: string }) => {
      const { id, doc } = await registry.open(p);
      return { documentId: id, migration: doc.migration, summary: doc.summary() };
    }),
  );

  server.registerTool(
    "linea_save_document",
    {
      title: "Save .linea file",
      description: "Save the document to disk as .linea JSON.",
      inputSchema: { path: z.string(), documentId },
    },
    run(async ({ path: p, documentId: idArg }: { path: string; documentId?: string }) => {
      const { doc } = registry.get(idArg);
      await doc.save(p);
      return { saved: p };
    }),
  );

  server.registerTool(
    "linea_export",
    {
      title: "Export document",
      description: "Write the document to disk as svg | png | pdf | dxf | dwg.",
      inputSchema: {
        format: z.enum(["svg", "png", "pdf", "dxf", "dwg"]),
        path: z.string(),
        layout: z.string().optional().describe("Render a layout instead of model space (svg/png)"),
        documentId,
      },
    },
    run(async ({ format, path: p, layout, documentId: idArg }: {
      format: "svg" | "png" | "pdf" | "dxf" | "dwg";
      path: string;
      layout?: string;
      documentId?: string;
    }) => {
      const { doc } = registry.get(idArg);
      if (format === "svg") await doc.exportSvg(p, { layout });
      else if (format === "png") await doc.exportPng(p, { layout });
      else if (format === "pdf") await doc.exportPdf(p);
      else if (format === "dwg") await doc.exportDwg(p);
      else await doc.exportDxf(p);
      return { exported: p };
    }),
  );

  // --- the MCP App: the full editor, in chat ---------------------------------

  registerAppTool(
    server,
    "linea_show_document",
    {
      title: "Show Linea document",
      description:
        "Open the document in the FULL interactive Linea editor INSIDE the " +
        "chat: the user can view, pan/zoom, draw, snap, dimension, and edit; " +
        "their changes flow back into the document. Call this after creating " +
        "or meaningfully changing a document, or whenever the user wants to " +
        "see or edit it.",
      inputSchema: { documentId },
      _meta: { ui: { resourceUri: EDITOR_RESOURCE_URI } },
    },
    (async ({ documentId: idArg }: { documentId?: string }) => {
      try {
        const { id, doc } = registry.get(idArg);
        return {
          content: [
            {
              type: "text" as const,
              text: `Showing "${doc.document.name}" in the in-chat editor (${doc.objects.length} model objects)`,
            },
          ],
          structuredContent: docPayload(registry, id, doc) as unknown as Record<string, unknown>,
        };
      } catch (e) {
        return toolError(e);
      }
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
    }) as any,
  );

  registerAppResource(
    server,
    "Linea editor",
    EDITOR_RESOURCE_URI,
    { mimeType: RESOURCE_MIME_TYPE },
    async () => ({
      contents: [
        {
          uri: EDITOR_RESOURCE_URI,
          mimeType: RESOURCE_MIME_TYPE,
          text: await (opts.editorHtml ??
            (async () => {
              const here = path.dirname(fileURLToPath(import.meta.url));
              // Bundled server: editor.html sits next to dist/server.js.
              // Dev (tsx src/server.ts): it lives in the sibling dist/.
              return readFile(path.join(here, "editor.html"), "utf-8").catch(
                () =>
                  readFile(path.join(here, "..", "dist", "editor.html"), "utf-8"),
              );
            }))(),
        },
      ],
    }),
  );
}
